    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_salesLine">_salesLine</param>
    /// <param name = "_inventDim">_inventDim</param>
    /// <returns></returns>
    boolean salesLine_validateWrite(SalesLine _salesLine, InventDim _inventDim)
    {
        boolean     ret = next salesLine_validateWrite(_salesLine, _inventDim);

        // MPJ-21310
        if(ret)
        {
            var sub = METSalesItemSubstitution::construct(
                _salesLine,
                _inventDim,
                METSalesItemSubstitutionEventSource::Creation,
                true);
            ret = sub.run();
        }
    
        return ret;
    }

/// <summary>
/// CoC
/// </summary>
/// <returns>Result</returns>
public boolean useAlternativeItem()
{
    boolean ret = next useAlternativeItem();
    ret = false;    // Use extended substitution logic in place of standard check. Possibly config to control this.
    return ret;
}
